-- FoodTrail starter catalogue synced from the master tracker.
-- Run schema.sql first.
on conflict (id) do update set
  name=excluded.name, area=excluded.area, category=excluded.category, source=excluded.source,
  source_url=excluded.source_url, budget_per_person=excluded.budget_per_person, maps_url=excluded.maps_url,
  verification_status=excluded.verification_status, notes=excluded.notes;
